import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"47、【困】 坎下兌上","description":"溫公易說 - 47、【困】 坎下兌上","frontmatter":{"title":"47、【困】 坎下兌上","description":"溫公易說 - 47、【困】 坎下兌上"},"headers":[],"relativePath":"classics/wengong/048.md","filePath":"classics/wengong/048.md"}'),l={name:"classics/wengong/048.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_47、【困】-坎下兌上" tabindex="-1">47、【困】 坎下兌上 <a class="header-anchor" href="#_47、【困】-坎下兌上" aria-label="Permalink to “47、【困】 坎下兌上”">​</a></h1><h3 id="彖曰-困-剛揜也。險以說-困而不失其所-亨-其唯君子乎-貞大人吉-以剛中也。有言不信-尚口乃窮也。" tabindex="-1">彖曰：困，剛揜也。險以說，困而不失其所，亨，其唯君子乎？貞大人吉，以剛中也。有言不信，尚口乃窮也。 <a class="header-anchor" href="#彖曰-困-剛揜也。險以說-困而不失其所-亨-其唯君子乎-貞大人吉-以剛中也。有言不信-尚口乃窮也。" aria-label="Permalink to “彖曰：困，剛揜也。險以說，困而不失其所，亨，其唯君子乎？貞大人吉，以剛中也。有言不信，尚口乃窮也。”">​</a></h3><h3 id="象曰-澤無水-困。君子以致命遂志。" tabindex="-1">象曰：澤無水，困。君子以致命遂志。 <a class="header-anchor" href="#象曰-澤無水-困。君子以致命遂志。" aria-label="Permalink to “象曰：澤無水，困。君子以致命遂志。”">​</a></h3><h3 id="初六-臀困於株木-入於幽谷-三歲不覿-象曰-入於幽谷-幽不明也。" tabindex="-1">初六：臀困於株木，入於幽谷，三歲不覿 象曰：入於幽谷，幽不明也。 <a class="header-anchor" href="#初六-臀困於株木-入於幽谷-三歲不覿-象曰-入於幽谷-幽不明也。" aria-label="Permalink to “初六：臀困於株木，入於幽谷，三歲不覿 象曰：入於幽谷，幽不明也。”">​</a></h3><p>谷者，險而窮下之象也。</p><h3 id="九二-困於酒食-朱紱方來-利用享祀-徵兇無咎-象曰-困於酒食-中有慶也。" tabindex="-1">九二：困於酒食，朱紱方來，利用享祀，徵兇無咎 象曰：困於酒食，中有慶也。 <a class="header-anchor" href="#九二-困於酒食-朱紱方來-利用享祀-徵兇無咎-象曰-困於酒食-中有慶也。" aria-label="Permalink to “九二：困於酒食，朱紱方來，利用享祀，徵兇無咎 象曰：困於酒食，中有慶也。”">​</a></h3><h3 id="六三-困於石-據於蒺藜-入於其宮-不見其妻-兇-象曰-據於蒺藜-乘剛也。入於其宮-不見其妻-不祥也。" tabindex="-1">六三：困於石，據於蒺藜，入於其宮，不見其妻，兇 象曰：據於蒺藜，乘剛也。入於其宮，不見其妻，不祥也。 <a class="header-anchor" href="#六三-困於石-據於蒺藜-入於其宮-不見其妻-兇-象曰-據於蒺藜-乘剛也。入於其宮-不見其妻-不祥也。" aria-label="Permalink to “六三：困於石，據於蒺藜，入於其宮，不見其妻，兇 象曰：據於蒺藜，乘剛也。入於其宮，不見其妻，不祥也。”">​</a></h3><h3 id="九四-來徐徐-困於金車-吝有終-象曰-來徐徐-志在下也。雖不當位-有與也。" tabindex="-1">九四：來徐徐，困於金車，吝有終 象曰：來徐徐，志在下也。雖不當位，有與也。 <a class="header-anchor" href="#九四-來徐徐-困於金車-吝有終-象曰-來徐徐-志在下也。雖不當位-有與也。" aria-label="Permalink to “九四：來徐徐，困於金車，吝有終 象曰：來徐徐，志在下也。雖不當位，有與也。”">​</a></h3><h3 id="九五-劓刖-困於赤紱-乃徐有說-利用祭祀-象曰-劓刖-志未得也。乃徐有說-以中直也。利用祭祀-受福也。" tabindex="-1">九五：劓刖，困於赤紱，乃徐有說，利用祭祀 象曰：劓刖，志未得也。乃徐有說，以中直也。利用祭祀，受福也。 <a class="header-anchor" href="#九五-劓刖-困於赤紱-乃徐有說-利用祭祀-象曰-劓刖-志未得也。乃徐有說-以中直也。利用祭祀-受福也。" aria-label="Permalink to “九五：劓刖，困於赤紱，乃徐有說，利用祭祀 象曰：劓刖，志未得也。乃徐有說，以中直也。利用祭祀，受福也。”">​</a></h3><h3 id="上六-困於葛藟-於臲卼-曰動悔有悔-徵吉-象曰-困於葛藟-未當也。動悔有悔-吉行也。" tabindex="-1">上六：困於葛藟，於臲卼，曰動悔有悔，徵吉 象曰：困於葛藟，未當也。動悔有悔，吉行也。 <a class="header-anchor" href="#上六-困於葛藟-於臲卼-曰動悔有悔-徵吉-象曰-困於葛藟-未當也。動悔有悔-吉行也。" aria-label="Permalink to “上六：困於葛藟，於臲卼，曰動悔有悔，徵吉 象曰：困於葛藟，未當也。動悔有悔，吉行也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
